{
  "title": "古墓绝艺",
  "scene": "你踏入了险境重重的古墓之中，这里尘封着无数武林绝学。幽暗的墓室里传来阵阵低沉的回声，空气中弥漫着淡淡的灰尘味。石壁上雕刻着古老的壁画，描绘着一代宗师的生平事迹。墓室尽头隐约可见一扇铁门，门边刻着一行字迹：“洞门封锁，非江湖正道莫入。”",
  "goal": "找到隐藏在古墓之中的绝世武功秘籍。",
  "choices": [
    {
      "id": "A",
      "text": "按剑破石，尝试用剑尖轻戳石壁上的一处隐蔽刻痕。",
      "outcome": "刻痕在剑尖的触碰下发出细微的‘喀嚓’声，一扇暗门慢慢开启。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "仔细观察壁画，试图从中找到开启机关的线索。",
      "outcome": "你发现壁画上描绘的是一场古代的武林比武，但并无直接线索指向铁门。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "用力撞击铁门，尝试用武力将其打开。",
      "outcome": "巨大的力量几乎震碎石壁，反而引起了机关的警报，从暗处窜出数名蒙面人，将你团团围住。",
      "result": "fail",
      "next": "bad_end"
    }
  ]
}
